# A kill switch: one setting that sends every request to the old manual path
FLAGS = {"ai_summaries": True}      # in real life this lives in a flag service or config table

def summarise(claim_text):
    if not FLAGS["ai_summaries"]:
        return "QUEUED for manual summary"      # the safe fallback users had before
    if "scan.pdf" in claim_text:
        raise RuntimeError("document service timeout")
    return "summary ok"

def handle(claim_text):
    try:
        return summarise(claim_text)
    except RuntimeError:
        return "ERROR shown to user"

claims = ["Water damage, kitchen", "Car scan.pdf attached", "Hail on roof"]
print([handle(c) for c in claims])

FLAGS["ai_summaries"] = False       # the incident commander flips the switch
print([handle(c) for c in claims])

# Output:
# -> ['summary ok', 'ERROR shown to user', 'summary ok']
# -> ['QUEUED for manual summary', 'QUEUED for manual summary', 'QUEUED for manual summary']
